BEGIN; SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims', '{"role":"authenticated","sub":"aaaaaaaa-1111-4111-8111-111111111111"}',true);
SELECT security_test.check('share valid payload accepted', '1', 'WITH added AS (INSERT INTO public.shared_lists(slug,list_id,payload) VALUES (''newgood001'',''user:aaaaaaaa-1111-4111-8111-111111111111'',''{"movies":[],"displayName":"Synthetic"}'') RETURNING 1) SELECT count(*)::text FROM added');
SELECT security_test.check('share extra payload insert rejected', 'error:23514', 'INSERT INTO public.shared_lists(slug,list_id,payload) VALUES (''newbad0001'',''user:aaaaaaaa-1111-4111-8111-111111111111'',''{"movies":[],"private":"test"}'')');
SELECT security_test.check('share extra payload update rejected', 'error:23514', 'UPDATE public.shared_lists SET payload=''{"movies":[],"private":"test"}'' WHERE slug=''newgood001''');
SELECT security_test.check('legacy extra-key snapshot remains readable by owner', '1', 'SELECT count(*)::text FROM public.shared_lists WHERE slug=''legacy0001''');
SELECT security_test.check('legacy extra-key snapshot can be revoked unchanged', '1', 'WITH changed AS (UPDATE public.shared_lists SET revoked=true WHERE slug=''legacy0001'' RETURNING 1) SELECT count(*)::text FROM changed');
SELECT security_test.check('owner reads legacy revoked snapshot', 'true', 'SELECT revoked::text FROM public.shared_lists WHERE slug=''legacy0001''');
SELECT security_test.check('legacy payload rewrite must become valid', 'error:23514', 'UPDATE public.shared_lists SET payload=payload WHERE slug=''legacy0001''');
SELECT security_test.check('legacy payload can be replaced with supported fields', '1', 'WITH changed AS (UPDATE public.shared_lists SET payload=''{"movies":[]}'' WHERE slug=''legacy0001'' RETURNING 1) SELECT count(*)::text FROM changed');
SELECT security_test.check('owner can delete share', '1', 'WITH removed AS (DELETE FROM public.shared_lists WHERE slug=''newgood001'' RETURNING 1) SELECT count(*)::text FROM removed');
SELECT security_test.check('share trigger direct execution denied', 'error:42501', 'SELECT public.enforce_shared_lists_payload_fields()');
ROLLBACK;
BEGIN; SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims', '{"role":"authenticated","sub":"aaaaaaaa-1111-4111-8111-111111111111"}',true);
SELECT security_test.check('rankings owner reads original', '1', 'SELECT count(*)::text FROM public.rankings WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111''');
SELECT security_test.check('rankings owner cannot read foreign', '0', 'SELECT count(*)::text FROM public.rankings WHERE list_id=''user:bbbbbbbb-2222-4222-8222-222222222222''');
SELECT security_test.check('rankings foreign update denied', '0', 'WITH changed AS (UPDATE public.rankings SET movies=movies WHERE list_id=''user:bbbbbbbb-2222-4222-8222-222222222222'' RETURNING 1) SELECT count(*)::text FROM changed');
SELECT security_test.check('rankings owner transfer rejected', 'error:42501', 'UPDATE public.rankings SET list_id=''user:cccccccc-3333-4333-8333-333333333333'' WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111''');
SELECT security_test.check('rankings conditional replacement saves', '1', 'WITH changed AS (UPDATE public.rankings SET movies=''[]'',updated_at=''2026-10-09T12:00:00Z'' WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111'' AND updated_at=(SELECT updated_at FROM public.rankings WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111'') RETURNING 1) SELECT count(*)::text FROM changed');
SELECT security_test.check('rankings stale conditional replacement refuses', '0', 'WITH changed AS (UPDATE public.rankings SET movies=''[]'' WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111'' AND updated_at=''2000-01-01'' RETURNING 1) SELECT count(*)::text FROM changed');
SELECT security_test.check('rankings owner backup reads replacement', 'true', 'SELECT (movies=''[]''::jsonb)::text FROM public.rankings WHERE list_id=''user:aaaaaaaa-1111-4111-8111-111111111111''');
ROLLBACK;
